#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, zlib
from pathlib import Path

class PatchError(RuntimeError): pass

def dec(s): return zlib.decompress(base64.b64decode(s)).decode()
def rb(t,a,b,r,n):
    x=t.find(a)
    if x<0: raise PatchError(f"{n}: start anchor not found")
    y=t.find(b,x)
    if y<0: raise PatchError(f"{n}: end anchor not found")
    return t[:x]+r+t[y:]
def ro(t,a,b,n):
    c=t.count(a)
    if c!=1: raise PatchError(f"{n}: expected 1 match, found {c}")
    return t.replace(a,b,1)

BLOBS = {
    'V9_HELPERS': '',
    'V9_HOME': '',
    'V9_WORKSHOP': '',
    'V9_CUSTOM': '',
    'V9_SYSTEM': '',
}

def patch_hub(repo: Path):
    p=repo/'src'/'smart_hub.cpp'
    if not p.exists(): raise PatchError('smart_hub.cpp missing; apply v8.3 RC3 first')
    t=p.read_text()
    if '#include <math.h>' not in t:
        t=ro(t,'#include <time.h>\n','#include <time.h>\n#include <math.h>\n','math include')
    H,HOME,WORK,CUSTOM,SYSTEM=(dec(BLOBS[k]) for k in ('V9_HELPERS','V9_HOME','V9_WORKSHOP','V9_CUSTOM','V9_SYSTEM'))
    t=rb(t,'static void drawPageDots(uint8_t active) {','static void drawHome(bool full) {',H+'static void drawHome(bool full) {','helpers')
    t=t.replace('static void drawHome(bool full) {static void drawHome(bool full) {','static void drawHome(bool full) {',1)
    t=rb(t,'static void drawHome(bool full) {','static void drawWorkshop(bool full) {',HOME+'static void drawWorkshop(bool full) {','home')
    t=t.replace('static void drawWorkshop(bool full) {static void drawWorkshop(bool full) {','static void drawWorkshop(bool full) {',1)
    t=rb(t,'static void drawWorkshop(bool full) {','static void drawCustom(bool full) {',WORK+'static void drawCustom(bool full) {','workshop')
    t=t.replace('static void drawCustom(bool full) {static void drawCustom(bool full) {','static void drawCustom(bool full) {',1)
    t=rb(t,'static void drawCustom(bool full) {','static void drawSystem(bool full) {',CUSTOM+'static void drawSystem(bool full) {','custom')
    t=t.replace('static void drawSystem(bool full) {static void drawSystem(bool full) {','static void drawSystem(bool full) {',1)
    t=rb(t,'static void drawSystem(bool full) {','} // namespace',SYSTEM+'} // namespace','system')
    t=t.replace('} // namespace} // namespace','} // namespace',1)
    marker='// Smart Home v9.0 visual command-center evolution RC1'
    if marker not in t: t += '\n'+marker+'\n'
    for n in ['UI_ORANGE','uiPrinterArt','uiProgressRing','uiSpool','uiBottomNav','drawHeader("HOME", "v9 UI", 0)','drawHeader("WORKSHOP", "LIVE HUB", 1)','drawHeader("SYSTEM", "v9 UI RC1", 3)','PORTAL CODE','RAM session • rotates on reboot','session + SHA-256']:
        if n not in t: raise PatchError('visual contract missing: '+n)
    for n in ['drawHeader("HOME", "Smart Home v8.3", 0)','drawHeader("SYSTEM", "Smart Home v8.3 RC3", 3)','Digest auth + same-origin protection']:
        if n in t: raise PatchError('legacy visual contract remains: '+n)
    p.write_text(t)

def patch_build(repo: Path):
    p=repo/'include'/'smart_home_build.h'; t=p.read_text()
    t=ro(t,'#define SMART_HOME_VERSION "v8.3"','#define SMART_HOME_VERSION "v9.0"','version')
    t=ro(t,'#define SMART_HOME_PROFILE "security-hardened"','#define SMART_HOME_PROFILE "visual-command-center"','profile')
    t=ro(t,'#define SMART_HOME_BUILD_LABEL "Smart Home v8.3 RC3"','#define SMART_HOME_BUILD_LABEL "Smart Home v9.0 UI RC1"','label')
    p.write_text(t)

def apply(repo: Path): patch_hub(repo); patch_build(repo)

if __name__=='__main__':
    ap=argparse.ArgumentParser(); ap.add_argument('--repo',required=True); ap.add_argument('--apply',action='store_true'); a=ap.parse_args()
    if not a.apply: raise SystemExit('Pass --apply')
    apply(Path(a.repo)); print('Smart Home v9.0 UI RC1 visual command-center patch applied')
